from document_models import ExpenseRecord, LineItem


def normalize_expense(extracted_data: dict) -> ExpenseRecord:
    document_type = list(extracted_data.keys())[0]
    data = extracted_data[document_type][0]

    if document_type == "invoices":
        return ExpenseRecord(
            document_type="invoice",
            vendor_name=data.get("vendor"),
            transaction_date=data.get("date"),
            total_amount=data.get("total"),
            line_items=[LineItem(**item) for item in data.get("line_items", [])]
        )
    elif document_type == "receipts":
        return ExpenseRecord(
            document_type="receipt",
            merchant_name=data.get("merchant"),
            tax_amount=data.get("tax"),
            total_amount=data.get("total"),
            line_items=[LineItem(**item) for item in data.get("items", [])]
        )
    else:
        raise ValueError(f"Unknown document type: {document_type}")

from typing import List
from document_models import ExpenseRecord


def validate_document_fields(expense_record: ExpenseRecord) -> List[str]:
    errors = []
    if expense_record.document_type == "invoice":
        if not expense_record.vendor_name:
            errors.append("Invoice must have a vendor name.")
        if not expense_record.transaction_date:
            errors.append("Invoice must have a transaction date.")
        if not expense_record.total_amount:
            errors.append("Invoice must have a total amount.")
    elif expense_record.document_type == "receipt":
        if not expense_record.merchant_name:
            errors.append("Receipt must have a merchant name.")
        if not expense_record.total_amount:
            errors.append("Receipt must have a total amount.")

    # Example of confidence score validation (if scores were available in ExpenseRecord)
    # if expense_record.total_amount_confidence and expense_record.total_amount_confidence < 0.7:
    #     errors.append("Total amount confidence is too low.")

    return errors

import os
import google.generativeai as genai
from document_models import ExpenseRecord
from document_client import load_document_config

def summarize_invoice_fields(expense_record: ExpenseRecord) -> str:
    config = load_document_config()
    genai.configure(api_key=os.environ.get("GEMINI_API_KEY"))
    model = genai.GenerativeModel(config.model_id)

    summary_prompt = f"""Summarize the following invoice details in a concise manner:
    Vendor: {expense_record.vendor_name or 'N/A'}
    Date: {expense_record.transaction_date or 'N/A'}
    Total: {expense_record.total_amount or 'N/A'}
    Line Items: {', '.join([item.description for item in expense_record.line_items]) if expense_record.line_items else 'N/A'}
    """
    response = model.generate_content(summary_prompt)
    return response.text
